131: export async function closeSeatProcess(options: {
132:   child: ChildProcess;
133:   exited: Promise<ProcessExit>;
134:   timeoutMs: number;
135:   recordedStartTicks: string | null;
136: }): Promise<SeatCloseResult> {
137:   const { child, exited, timeoutMs, recordedStartTicks } = options;
138:   child.stdin?.end();
139:   const graceful = await raceWithTimeout(exited, timeoutMs);
140:   if (graceful !== "timeout") {
141:     return {
142:       outcome: "exited",
143:       exitCode: graceful.code ?? (graceful.signal ? 1 : 0),
144:       signal: graceful.signal,
145:     };
146:   }
147:   const killed = await terminateProcessTree(child, recordedStartTicks);
148:   if (killed === "already-exited") {
149:     // 句柄在超时与强杀之间刚好退了：这仍是它自己退的，按真实退出码报。
150:     const late = await raceWithTimeout(exited, AFTER_KILL_WAIT_MS);
151:     if (late !== "timeout") {
152:       return {
153:         outcome: "exited",
154:         exitCode: late.code ?? (late.signal ? 1 : 0),
155:         signal: late.signal,
156:       };
157:     }
158:   }
159:   if (killed === "refused") {
160:     return {
161:       outcome: "kill-refused",
162:       exitCode: SEAT_CLOSE_REFUSED_EXIT_CODE,
163:       signal: null,
164:     };
165:   }
166:   const after = await raceWithTimeout(exited, AFTER_KILL_WAIT_MS);
167:   return {
168:     outcome: "timeout-killed",
169:     exitCode: SEAT_CLOSE_TIMEOUT_EXIT_CODE,
170:     signal: after === "timeout" ? null : after.signal,
171:   };

