14: function fsyncDirectory(directory: string): void {
15:   try {
16:     const descriptor = openSync(directory, "r");
17:     try {
18:       fsyncSync(descriptor);
19:     } finally {
20:       closeSync(descriptor);
21:     }
22:   } catch {
23:     // Windows can reject opening a directory for fsync; the file itself was fsynced.
24:   }
