27: export function atomicWriteFile(file: string, content: string): void {
28:   mkdirSync(dirname(file), { recursive: true });
29:   const temporary = `${file}.${process.pid}.${randomUUID()}.tmp`;
30:   const descriptor = openSync(temporary, "wx", 0o600);
31:   try {
32:     writeFileSync(descriptor, content, "utf8");
33:     fsyncSync(descriptor);
34:   } finally {
35:     closeSync(descriptor);
36:   }
37:   renameSync(temporary, file);
38:   fsyncDirectory(dirname(file));
39: }
